import{_ as t,o,c as a,a2 as i}from"./chunks/framework.k9nOhppk.js";const m=JSON.parse(`{"title":"What's left","description":"","frontmatter":{"title":"What's left"},"headers":[],"relativePath":"whats-left.md","filePath":"whats-left.md","lastUpdated":1791864160000}`),r={name:"whats-left.md"};function n(d,e,s,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="what-s-left" tabindex="-1">What&#39;s left <a class="header-anchor" href="#what-s-left" aria-label="Permalink to &quot;What&#39;s left&quot;">​</a></h1><p>Every open item, as of 2026-10-13, in one list. <a href="/future-of-eyelang">The future of Eyelang</a> tells the story: what Eyelang is, what it can do today and where it is going. This page is the checklist behind it. Task by task, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/ROADMAP.md" target="_blank" rel="noreferrer">ROADMAP.md</a> and the <a href="https://github.com/ruxxzebre/eyelang/issues" target="_blank" rel="noreferrer">GitHub issues</a> are the record; feature by feature, <a href="/reference/status">What runs today</a> is. When an item here is done, remove it in the same commit.</p><h2 id="a-before-the-native-focus-checkpoint" tabindex="-1">A. Before the native-focus checkpoint <a class="header-anchor" href="#a-before-the-native-focus-checkpoint" aria-label="Permalink to &quot;A. Before the native-focus checkpoint&quot;">​</a></h2><p>ROADMAP&#39;s &quot;What&#39;s next&quot; opens with the checkpoint: when it is reached, every session works on compiling and the native port, and new features wait for v0.4.</p><ul><li><strong>#117</strong> The rest of 7.13: maps specialised per key type (1.62× Go&#39;s time today), and <code>String</code> and <code>Bytes</code> as views whose slices share their buffer.</li></ul><h2 id="b-v0-4-native-compilation" tabindex="-1">B. v0.4: native compilation <a class="header-anchor" href="#b-v0-4-native-compilation" aria-label="Permalink to &quot;B. v0.4: native compilation&quot;">​</a></h2><ul><li><strong>#79</strong> 7.6, the runner hosts compiled programs. The Go runner already runs compiled entity methods and jobs, answers their callbacks and host steps, and carries the program in the binary (shown with a hand-written C program). Left: <ul><li>the C back end writes the program&#39;s tables and entry points: entity methods, jobs as state machines, encoding and decoding saved values, <code>main</code> and tests;</li><li><code>eye build --runner</code> builds real programs, with the runner&#39;s Go source embedded;</li><li><code>testdata/programs/entities</code> runs natively under the runner;</li><li><strong>the morning digest runs as a native job</strong> on the journal and on Postgres, killed and resumed, with its idle memory and resume time recorded beside the interpreter&#39;s.</li></ul></li><li><strong>The v0.4 release:</strong> a tag, binaries for the five targets, release notes.</li></ul><h2 id="c-native-code-after-v0-4-v0-4-x" tabindex="-1">C. Native code after v0.4 (v0.4.x) <a class="header-anchor" href="#c-native-code-after-v0-4-v0-4-x" aria-label="Permalink to &quot;C. Native code after v0.4 (v0.4.x)&quot;">​</a></h2><ul><li><strong>#114</strong> 7.11, faster than Go on every benchmark, not only on the geometric mean (0.85× Go&#39;s time and 0.36× its memory today). <code>fib</code> is 1.69×, mostly <code>Int</code> overflow checks.</li><li><strong>#115</strong> 7.12, a <code>match</code> arm that builds a value of the same size reuses the matched cell, and a failing test frees what it allocated.</li><li><strong>Compile speed</strong> (open question 47): the owner&#39;s targets for building a million lines.</li><li>Smaller native items: <ul><li><code>x / -7</code> isn&#39;t turned into a multiplication;</li><li>a small program starts at 0.28 MB, up from 0.16 MB;</li><li>a cold <code>-O2</code> build is a few seconds slower since the runtime compiles with the program;</li><li>the Windows paths (<code>process.run</code>, the stack thread) are cross-compiled but never run;</li><li>tasks and channels run in the Go runner, not in compiled C;</li><li><code>d.seconds()</code>, <code>d.millis()</code>, <code>d / n</code> and <code>d / e</code> on a <code>Duration</code> (#146) run in the interpreter only;</li><li>a <code>wasm32-wasi</code> target for <code>eye build</code>.</li></ul></li></ul><h2 id="d-finishing-v0-3-contracts-and-agents" tabindex="-1">D. Finishing v0.3: contracts and agents <a class="header-anchor" href="#d-finishing-v0-3-contracts-and-agents" aria-label="Permalink to &quot;D. Finishing v0.3: contracts and agents&quot;">​</a></h2><ul><li><strong>#58</strong> 6.6, Notify&#39;s boundary generated from its contract, in the homelab repository.</li><li><strong>#60</strong> 6.8, the <code>agents</code> module: coding-agent sessions owned by jobs.</li><li><strong>The v0.3 release:</strong> the owner decides whether to release before 6.6 and 6.8.</li></ul><h2 id="e-owed-by-releases-already-made" tabindex="-1">E. Owed by releases already made <a class="header-anchor" href="#e-owed-by-releases-already-made" aria-label="Permalink to &quot;E. Owed by releases already made&quot;">​</a></h2><ul><li>Phase 5&#39;s exit criterion: one good morning run of the digest in the homelab, then the owner&#39;s decision on replacing the TypeScript digest.</li><li>Move the homelab digest&#39;s pin to the latest <code>dev</code> (retries, clear errors, effort, checkpoints).</li><li>The decision log should say that pipelines over entity sets run in memory until several runners share a database.</li></ul><h2 id="f-other-open-issues" tabindex="-1">F. Other open issues <a class="header-anchor" href="#f-other-open-issues" aria-label="Permalink to &quot;F. Other open issues&quot;">​</a></h2><ul><li><strong>#144</strong> Webhooks to many URLs: <code>http</code> has only <code>get</code>, and a contract has one base URL.</li><li><strong>#148</strong> Replace the remaining homelab-specific teaching examples in the docs.</li><li><strong>#149</strong> <code>main</code> is stale (May, Go 1.25): update it, or make <code>dev</code> the default branch.</li><li><strong>#152</strong> <code>llms-full.txt</code> with the whole reference.</li><li><strong>#153</strong> Standard library gaps: a secure random token, and JSON into typed values.</li></ul><h2 id="g-self-hosting" tabindex="-1">G. Self-hosting <a class="header-anchor" href="#g-self-hosting" aria-label="Permalink to &quot;G. Self-hosting&quot;">​</a></h2><ul><li><strong>#82</strong> The compiler, written in Eyelang, builds itself. The lexer (S.1) is done; the parser, the formatter, <code>eye doc</code> and the checker come next, then the bootstrap.</li><li><strong>#116</strong> S.2, the runner in Eyelang, so a job program has no Go in it and can beat Go on memory.</li></ul><h2 id="h-parked-until-v0-4-is-out" tabindex="-1">H. Parked until v0.4 is out <a class="header-anchor" href="#h-parked-until-v0-4-is-out" aria-label="Permalink to &quot;H. Parked until v0.4 is out&quot;">​</a></h2><ul><li>The package manager, phases P0 to P3 (open questions 5 and 18).</li><li>Open question 41: runs pinned to the code they started on.</li></ul><h2 id="i-open-questions-not-yet-decided" tabindex="-1">I. Open questions not yet decided <a class="header-anchor" href="#i-open-questions-not-yet-decided" aria-label="Permalink to &quot;I. Open questions not yet decided&quot;">​</a></h2><p>From <a href="/design/open-questions">SPECS.md&#39;s open questions</a>:</p><table tabindex="0"><thead><tr><th>#</th><th>Question</th></tr></thead><tbody><tr><td>1</td><td>Time conditions in views (&quot;idle for 20 minutes&quot;)</td></tr><tr><td>3</td><td>Exposing entities and jobs to other services</td></tr><tr><td>5</td><td>Packages</td></tr><tr><td>7</td><td>Metaprogramming after v1.0</td></tr><tr><td>10</td><td>Streaming model output</td></tr><tr><td>11</td><td>Prompts as text files</td></tr><tr><td>12</td><td>Request-scoped values (a trace id, the current user)</td></tr><tr><td>13</td><td><code>eye fmt</code> and the two forms of <code>if</code></td></tr><tr><td>14</td><td><code>if let</code></td></tr><tr><td>18</td><td>Contracts shared by programs</td></tr><tr><td>23</td><td>Where <code>!</code> goes on a helper</td></tr><tr><td>24</td><td><code>dyn Store</code>, and traits that name their own type</td></tr><tr><td>26</td><td>What <code>@memory</code> measures</td></tr><tr><td>27</td><td>One flag for the store</td></tr><tr><td>28</td><td>Several runners on one database</td></tr><tr><td>29</td><td>The shape of task groups</td></tr><tr><td>30</td><td>Model prices and routing</td></tr><tr><td>31</td><td><code>Option</code> parameters with defaults</td></tr><tr><td>32</td><td>Time-travel debugging</td></tr><tr><td>33</td><td>Effects of a function that is only stored</td></tr><tr><td>35</td><td>Who may publish an event</td></tr><tr><td>36</td><td><code>@destructive</code> means two things</td></tr><tr><td>37</td><td>One shape for &quot;time ran out&quot;</td></tr><tr><td>38</td><td>Slices and memory</td></tr><tr><td>39</td><td>A module with two contracts</td></tr><tr><td>40</td><td>What <code>main</code> repeats</td></tr><tr><td>41</td><td>Runs pinned to the code they started on</td></tr><tr><td>44</td><td>Regex patterns checked at compile time, and raw strings</td></tr><tr><td>46</td><td>A permission model for effects</td></tr><tr><td>47</td><td>How fast a million lines compile</td></tr><tr><td>48</td><td>Events in the network policy</td></tr></tbody></table><h2 id="j-findings-without-an-issue" tabindex="-1">J. Findings without an issue <a class="header-anchor" href="#j-findings-without-an-issue" aria-label="Permalink to &quot;J. Findings without an issue&quot;">​</a></h2><ul><li>A generic private function that calls itself at a bigger type is reported by <code>eye check --lir</code>, not by <code>eye check</code>.</li><li>The lab&#39;s <code>trains.watch</code> stops growing in the homelab only once its pin moves past checkpoints.</li></ul><h2 id="k-v1-0" tabindex="-1">K. v1.0 <a class="header-anchor" href="#k-v1-0" aria-label="Permalink to &quot;K. v1.0&quot;">​</a></h2><p>A syntax freeze, migration tooling (<code>eye fix</code> grows into it), <code>eye why</code>, hot code replacement, and complete documentation.</p><h2 id="l-decisions-waiting-on-the-owner" tabindex="-1">L. Decisions waiting on the owner <a class="header-anchor" href="#l-decisions-waiting-on-the-owner" aria-label="Permalink to &quot;L. Decisions waiting on the owner&quot;">​</a></h2><ol><li>Events need the contract&#39;s <code>@auth</code>: add <code>@auth</code> to the lab&#39;s Telegram contract, with Telegram&#39;s webhook secret header?</li><li>Should a refused request (a 404 from a missing URL) be retryable, through a fault of its own?</li><li><code>0.0 == -0.0</code> is false, beside <code>NaN == NaN</code> being true: confirm.</li><li>Native recursion is limited by the stack&#39;s size, not by exactly 100,000 calls: keep?</li><li><code>regex</code> and <code>http.get</code> in compiled code are answered by the Go runner: keep?</li><li>Release v0.3 now?</li></ol>',28)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
